*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-base:       #0d0d0f;
  --bg-surface:    #18181c;
  --bg-elevated:   #222228;
  --bg-card:       #1c1c22;
  --border:        #2e2e38;
  --accent:        #e8c848;
  --accent-dim:    #c9a930;
  --accent-glow:   rgba(232,200,72,.18);
  --red:           #e84848;
  --green:         #3dba7a;
  --text-primary:  #f0f0f4;
  --text-secondary:#9898a8;
  --text-muted:    #5a5a6a;
  --radius-sm:     6px;
  --radius-md:     12px;
  --radius-lg:     20px;
  --shadow-card:   0 4px 24px rgba(0,0,0,.55);
  --transition:    0.2s ease;
  --font-sans:     'Inter', system-ui, -apple-system, sans-serif;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-base);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
}

img { display: block; max-width: 100%; }
a  { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul { list-style: none; }

/* ── Utilities ────────────────────────────────────────────── */
.visually-hidden {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}
.badge {
  display: inline-flex; align-items: center;
  padding: 3px 10px; border-radius: 99px;
  font-size: .7rem; font-weight: 700; letter-spacing: .06em;
  text-transform: uppercase;
}
.badge--sale   { background: var(--red);   color: #fff; }
.badge--new    { background: var(--green); color: #fff; }
.badge--hot    { background: var(--accent); color: #000; }
.badge--editor { background: var(--bg-elevated); color: var(--accent); border: 1px solid var(--border); }

.section-header {
  display: flex; align-items: baseline; justify-content: space-between;
  margin-bottom: 1.5rem;
}
.section-title {
  font-size: 1.35rem; font-weight: 700; letter-spacing: -.02em;
}
.section-link {
  font-size: .83rem; color: var(--accent); font-weight: 600;
  display: flex; align-items: center; gap: 4px;
  transition: gap var(--transition);
}
.section-link:hover { gap: 8px; }
.section-link::after { content: '→'; }

/* ── Skip link ───────────────────────────────────────────── */
.skip-link {
  position: absolute; top: -100%; left: 1rem; z-index: 9999;
  background: var(--accent); color: #000;
  padding: .5rem 1rem; border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  font-weight: 700; font-size: .9rem;
  transition: top .15s;
}
.skip-link:focus { top: 0; }

/* ── Navbar ──────────────────────────────────────────────── */
.navbar {
  position: sticky; top: 0; z-index: 100;
  background: rgba(13,13,15,.88);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}
.navbar__inner {
  max-width: 1280px; margin: 0 auto;
  padding: 0 1.5rem;
  display: flex; align-items: center; gap: 2rem;
  height: 64px;
}
.navbar__logo {
  font-size: 1.4rem; font-weight: 800; letter-spacing: -.04em;
  color: var(--text-primary);
  flex-shrink: 0;
}
.navbar__logo span { color: var(--accent); }

.navbar__nav { flex: 1; }
.navbar__nav ul {
  display: flex; gap: 1.75rem;
}
.navbar__nav a {
  font-size: .9rem; font-weight: 500; color: var(--text-secondary);
  transition: color var(--transition);
}
.navbar__nav a:hover,
.navbar__nav a[aria-current="page"] { color: var(--text-primary); }

.navbar__actions {
  display: flex; align-items: center; gap: .5rem;
}
.icon-btn {
  position: relative;
  width: 40px; height: 40px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: background var(--transition), color var(--transition);
}
.icon-btn:hover { background: var(--bg-elevated); color: var(--text-primary); }
.icon-btn svg { width: 20px; height: 20px; }

.cart-count {
  position: absolute; top: 4px; right: 4px;
  background: var(--accent); color: #000;
  font-size: .6rem; font-weight: 800;
  width: 16px; height: 16px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  line-height: 1;
}
.navbar__menu-toggle {
  display: none;
  width: 40px; height: 40px;
  flex-direction: column; justify-content: center; align-items: center;
  gap: 5px; border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: background var(--transition);
}
.navbar__menu-toggle:hover { background: var(--bg-elevated); }
.navbar__menu-toggle span {
  display: block; width: 20px; height: 2px;
  background: currentColor; border-radius: 2px;
  transition: transform .2s, opacity .2s;
}

/* ── Hero ────────────────────────────────────────────────── */
.hero {
  position: relative; overflow: hidden;
  min-height: 580px;
  display: flex; align-items: center;
  background: var(--bg-surface);
}
.hero__bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse 70% 60% at 75% 50%, rgba(232,200,72,.10) 0%, transparent 70%),
    radial-gradient(ellipse 40% 50% at 20% 80%, rgba(61,186,122,.07) 0%, transparent 60%);
}
.hero__grid-pattern {
  position: absolute; inset: 0; opacity: .04;
  background-image: linear-gradient(var(--border) 1px, transparent 1px),
                    linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 40px 40px;
}
.hero__inner {
  max-width: 1280px; margin: 0 auto;
  padding: 5rem 1.5rem;
  position: relative; z-index: 1;
  display: grid; grid-template-columns: 1fr 1fr; gap: 3rem;
  align-items: center;
}
.hero__eyebrow {
  display: flex; align-items: center; gap: .6rem;
  font-size: .78rem; font-weight: 600; letter-spacing: .12em;
  text-transform: uppercase; color: var(--accent);
  margin-bottom: 1.25rem;
}
.hero__eyebrow::before {
  content: ''; display: block; width: 28px; height: 2px;
  background: var(--accent);
}
.hero__title {
  font-size: clamp(2.2rem, 5vw, 3.5rem);
  font-weight: 800; letter-spacing: -.04em; line-height: 1.1;
  margin-bottom: 1.25rem;
}
.hero__title em { font-style: normal; color: var(--accent); }
.hero__desc {
  font-size: 1.05rem; color: var(--text-secondary);
  max-width: 440px; margin-bottom: 2rem; line-height: 1.7;
}
.hero__cta {
  display: flex; gap: 1rem; flex-wrap: wrap;
}
.btn {
  display: inline-flex; align-items: center; gap: .5rem;
  padding: .7rem 1.5rem; border-radius: var(--radius-sm);
  font-size: .93rem; font-weight: 700; letter-spacing: .01em;
  transition: transform var(--transition), box-shadow var(--transition), background var(--transition);
}
.btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
.btn--primary {
  background: var(--accent); color: #000;
  box-shadow: 0 0 0 0 var(--accent-glow);
}
.btn--primary:hover {
  background: var(--accent-dim);
  box-shadow: 0 6px 28px var(--accent-glow);
  transform: translateY(-1px);
}
.btn--ghost {
  background: transparent; color: var(--text-primary);
  border: 1px solid var(--border);
}
.btn--ghost:hover {
  background: var(--bg-elevated);
  border-color: var(--text-muted);
}
.hero__stats {
  display: flex; gap: 2rem; margin-top: 2.5rem;
}
.hero__stat strong {
  display: block; font-size: 1.6rem; font-weight: 800;
  color: var(--text-primary); letter-spacing: -.03em;
}
.hero__stat span { font-size: .8rem; color: var(--text-secondary); }

.hero__visual {
  display: flex; flex-direction: column; gap: 1rem;
}
.hero__product-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  display: flex; gap: 1.25rem; align-items: center;
  box-shadow: var(--shadow-card);
  transition: transform var(--transition), border-color var(--transition);
  cursor: pointer;
}
.hero__product-card:hover { transform: translateY(-2px); border-color: var(--accent); }
.hero__product-card--featured {
  background: linear-gradient(135deg, #1a1a22 0%, #13131a 100%);
}
.hero__product-img {
  width: 100px; height: 100px; border-radius: var(--radius-md);
  background: var(--bg-elevated);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0; font-size: 2.5rem;
}
.hero__product-info { flex: 1; min-width: 0; }
.hero__product-info h3 {
  font-size: 1rem; font-weight: 700; margin-bottom: .25rem;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.hero__product-info p { font-size: .82rem; color: var(--text-secondary); margin-bottom: .5rem; }
.hero__product-price { display: flex; align-items: center; gap: .5rem; }
.price-now { font-size: 1.1rem; font-weight: 800; color: var(--text-primary); }
.price-was { font-size: .82rem; color: var(--text-muted); text-decoration: line-through; }
.price-save { font-size: .75rem; font-weight: 700; color: var(--green); }

/* ── Announcement bar ────────────────────────────────────── */
.announce-bar {
  background: var(--accent); color: #000;
  text-align: center; padding: .55rem 1.5rem;
  font-size: .82rem; font-weight: 700; letter-spacing: .04em;
}
.announce-bar a { color: #000; text-decoration: underline; }

/* ── Main layout ─────────────────────────────────────────── */
main { max-width: 1280px; margin: 0 auto; padding: 3rem 1.5rem 5rem; }
.section { margin-bottom: 4.5rem; }

/* ── Category pills ──────────────────────────────────────── */
.categories {
  display: flex; gap: .75rem; flex-wrap: wrap;
  margin-bottom: 4.5rem;
}
.cat-pill {
  display: flex; align-items: center; gap: .6rem;
  padding: .6rem 1.2rem; border-radius: 99px;
  border: 1px solid var(--border);
  background: var(--bg-card);
  font-size: .85rem; font-weight: 600; color: var(--text-secondary);
  transition: background var(--transition), border-color var(--transition), color var(--transition), transform var(--transition);
}
.cat-pill:hover, .cat-pill[aria-pressed="true"] {
  background: var(--bg-elevated);
  border-color: var(--accent);
  color: var(--text-primary);
  transform: translateY(-1px);
}
.cat-pill__icon { font-size: 1.1rem; }

/* ── Product grid ────────────────────────────────────────── */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1.25rem;
}
.product-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
  position: relative;
}
.product-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-card);
  border-color: var(--bg-elevated);
}
.product-card:focus-within { outline: 2px solid var(--accent); outline-offset: 2px; }

.product-card__img {
  aspect-ratio: 1 / 1;
  background: var(--bg-elevated);
  display: flex; align-items: center; justify-content: center;
  font-size: 4rem; position: relative; overflow: hidden;
}
.product-card__img::after {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(circle at 50% 110%, rgba(232,200,72,.06), transparent 60%);
}
.product-card__badges {
  position: absolute; top: .6rem; left: .6rem;
  display: flex; flex-direction: column; gap: .35rem;
}
.product-card__wishlist {
  position: absolute; top: .5rem; right: .5rem;
  width: 32px; height: 32px;
  border-radius: 50%;
  background: rgba(13,13,15,.7);
  border: 1px solid var(--border);
  display: flex; align-items: center; justify-content: center;
  color: var(--text-muted); font-size: 1rem;
  transition: color var(--transition), background var(--transition);
  backdrop-filter: blur(4px);
}
.product-card__wishlist:hover,
.product-card__wishlist[aria-pressed="true"] {
  color: var(--red); background: rgba(232,72,72,.12);
}
.product-card__body { padding: .9rem; flex: 1; display: flex; flex-direction: column; }
.product-card__cat  { font-size: .7rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: .08em; margin-bottom: .3rem; }
.product-card__name { font-size: .93rem; font-weight: 600; margin-bottom: .4rem; line-height: 1.4; flex: 1; }
.product-card__rating { display: flex; align-items: center; gap: .35rem; margin-bottom: .6rem; }
.stars { color: var(--accent); font-size: .75rem; letter-spacing: .05em; }
.rating-count { font-size: .72rem; color: var(--text-muted); }
.product-card__footer { display: flex; align-items: center; justify-content: space-between; gap: .5rem; }
.product-card__price strong { font-size: 1.05rem; font-weight: 800; }
.product-card__price del { display: block; font-size: .75rem; color: var(--text-muted); }
.add-btn {
  width: 36px; height: 36px; border-radius: var(--radius-sm);
  background: var(--accent); color: #000;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.2rem; font-weight: 700;
  flex-shrink: 0;
  transition: background var(--transition), transform var(--transition);
}
.add-btn:hover { background: var(--accent-dim); transform: scale(1.08); }
.add-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

/* ── Deals section ───────────────────────────────────────── */
.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.25rem;
}
.deal-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  transition: transform var(--transition), border-color var(--transition);
}
.deal-card:hover { transform: translateY(-2px); border-color: var(--accent); }
.deal-card--wide { grid-column: span 2; }
.deal-card__img {
  width: 160px; flex-shrink: 0;
  background: var(--bg-elevated);
  display: flex; align-items: center; justify-content: center;
  font-size: 4.5rem;
}
.deal-card--wide .deal-card__img { width: 220px; font-size: 6rem; }
.deal-card__content {
  padding: 1.25rem; flex: 1; display: flex; flex-direction: column; justify-content: center; gap: .5rem;
}
.deal-card__title { font-size: 1rem; font-weight: 700; }
.deal-card--wide .deal-card__title { font-size: 1.25rem; }
.deal-card__desc { font-size: .82rem; color: var(--text-secondary); line-height: 1.55; }
.deal-card__pricing { display: flex; align-items: baseline; gap: .6rem; }
.deal-card__pricing .price-now { font-size: 1.4rem; }
.deal-card__timer {
  display: flex; align-items: center; gap: .4rem;
  font-size: .78rem; color: var(--red); font-weight: 600;
}
.deal-card__timer::before { content: '⏱'; }
.timer-unit {
  background: var(--bg-elevated); border: 1px solid var(--border);
  border-radius: 4px; padding: 2px 6px;
  font-size: .78rem; font-weight: 700; font-variant-numeric: tabular-nums;
  color: var(--text-primary);
  min-width: 28px; text-align: center;
}

/* ── Editorial grid ──────────────────────────────────────── */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 1.25rem;
}
.editorial-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform var(--transition), border-color var(--transition);
}
.editorial-card:hover { transform: translateY(-2px); border-color: var(--text-muted); }
.editorial-card--lead { grid-row: span 2; }
.editorial-card__thumb {
  background: var(--bg-elevated);
  display: flex; align-items: center; justify-content: center;
  font-size: 4rem;
}
.editorial-card--lead .editorial-card__thumb { height: 280px; font-size: 6rem; }
.editorial-card:not(.editorial-card--lead) .editorial-card__thumb { height: 160px; }
.editorial-card__body { padding: 1.1rem; flex: 1; display: flex; flex-direction: column; gap: .5rem; }
.editorial-card__meta { display: flex; align-items: center; gap: .6rem; flex-wrap: wrap; }
.editorial-card__date { font-size: .72rem; color: var(--text-muted); }
.editorial-card__title { font-size: .97rem; font-weight: 700; line-height: 1.4; }
.editorial-card--lead .editorial-card__title { font-size: 1.2rem; }
.editorial-card__excerpt { font-size: .82rem; color: var(--text-secondary); line-height: 1.6; flex: 1; }
.editorial-card__author {
  display: flex; align-items: center; gap: .5rem;
  padding-top: .6rem; border-top: 1px solid var(--border);
  font-size: .75rem; color: var(--text-muted);
}
.author-avatar {
  width: 24px; height: 24px; border-radius: 50%;
  background: var(--bg-elevated); border: 1px solid var(--border);
  display: flex; align-items: center; justify-content: center;
  font-size: .7rem;
}

/* ── Brand marquee ───────────────────────────────────────── */
.brands-section { margin-bottom: 4.5rem; overflow: hidden; }
.brands-label {
  text-align: center; font-size: .75rem; font-weight: 600;
  letter-spacing: .12em; text-transform: uppercase;
  color: var(--text-muted); margin-bottom: 1.25rem;
}
.brands-track {
  display: flex; gap: 2rem; align-items: center;
  animation: marquee 28s linear infinite;
  width: max-content;
}
.brands-track:hover { animation-play-state: paused; }
.brand-logo {
  flex-shrink: 0; padding: .65rem 1.5rem;
  border: 1px solid var(--border); border-radius: var(--radius-sm);
  background: var(--bg-card);
  font-size: .82rem; font-weight: 800; letter-spacing: .06em;
  color: var(--text-muted); text-transform: uppercase;
