*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-base:       #0d0d0f;
  --bg-surface:    #18181c;
  --bg-elevated:   #222228;
  --bg-card:       #1c1c22;
  --border:        #2e2e38;
  --accent:        #e8c848;
  --accent-dim:    #c9a930;
  --accent-glow:   rgba(232,200,72,.18);
  --red:           #e84848;
  --green:         #3dba7a;
  --text-primary:  #f0f0f4;
  --text-secondary:#9898a8;
  --text-muted:    #5a5a6a;
  --radius-sm:     6px;
  --radius-md:     12px;
  --radius-lg:     20px;
  --shadow-card:   0 4px 24px rgba(0,0,0,.55);
  --transition:    0.2s ease;
  --font-sans:     'Inter', system-ui, -apple-system, sans-serif;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-base);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
}

img { display: block; max-width: 100%; }
a  { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul { list-style: none; }

/* ── Utilities ────────────────────────────────────────────── */
.visually-hidden {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}
.badge {
  display: inline-flex; align-items: center;
  padding: 3px 10px; border-radius: 99px;
  font-size: .7rem; font-weight: 700; letter-spacing: .06em;
  text-transform: uppercase;
}
.badge--sale   { background: var(--red);   color: #fff; }
.badge--new    { background: var(--green); color: #fff; }
.badge--hot    { background: var(--accent); color: #000; }
.badge--editor { background: var(--bg-elevated); color: var(--accent); border: 1px solid var(--border); }

.section-header {
  display: flex; align-items: baseline; justify-content: space-between;
  margin-bottom: 1.5rem;
}
.section-title {
  font-size: 1.35rem; font-weight: 700; letter-spacing: -.02em;
}
.section-link {
  font-size: .83rem; color: var(--accent); font-weight: 600;
  display: flex; align-items: center; gap: 4px;
  transition: gap var(--transition);
}
.section-link:hover { gap: 8px; }
.section-link::after { content: '→'; }

/* ── Skip link ───────────────────────────────────────────── */
.skip-link {
  position: absolute; top: -100%; left: 1rem; z-index: 9999;
  background: var(--accent); color: #000;
  padding: .5rem 1rem; border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  font-weight: 700; font-size: .9rem;
  transition: top .15s;
}
.skip-link:focus { top: 0; }

/* ── Navbar ──────────────────────────────────────────────── */
.navbar {
  position: sticky; top: 0; z-index: 100;
  background: rgba(13,13,15,.88);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}
.navbar__inner {
  max-width: 1280px; margin: 0 auto;
  padding: 0 1.5rem;
  display: flex; align-items: center; gap: 2rem;
  height: 64px;
}
.navbar__logo {
  font-size: 1.4rem; font-weight: 800; letter-spacing: -.04em;
  color: var(--text-primary);
  flex-shrink: 0;
}
.navbar__logo span { color: var(--accent); }

.navbar__nav { flex: 1; }
.navbar__nav ul {
  display: flex; gap: 1.75rem;
}
.navbar__nav a {
  font-size: .9rem; font-weight: 500; color: var(--text-secondary);
  transition: color var(--transition);
}
.navbar__nav a:hover,
.navbar__nav a[aria-current="page"] { color: var(--text-primary); }

.navbar__actions {
  display: flex; align-items: center; gap: .5rem;
}
.icon-btn {
  position: relative;
  width: 40px; height: 40px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: background var(--transition), color var(--transition);
}
.icon-btn:hover { background: var(--bg-elevated); color: var(--text-primary); }
.icon-btn svg { width: 20px; height: 20px; }

.cart-count {
  position: absolute; top: 4px; right: 4px;
  background: var(--accent); color: #000;
  font-size: .6rem; font-weight: 800;
  width: 16px; height: 16px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  line-height: 1;
}
.navbar__menu-toggle {
  display: none;
  width: 40px; height: 40px;
  flex-direction: column; justify-content: center; align-items: center;
  gap: 5px; border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: background var(--transition);
}
.navbar__menu-toggle:hover { background: var(--bg-elevated); }
.navbar__menu-toggle span {
  display: block; width: 20px; height: 2px;
  background: currentColor; border-radius: 2px;
  transition: transform .2s, opacity .2s;
}

/* ── Hero ────────────────────────────────────────────────── */
.hero {
  position: relative; overflow: hidden;
  min-height: 580px;
  display: flex; align-items: center;
  background: var(--bg-surface);
}
.hero__bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse 70% 60% at 75% 50%, rgba(232,200,72,.10) 0%, transparent 70%),
    radial-gradient(ellipse 40% 50% at 20% 80%, rgba(61,186,122,.07) 0%, transparent 60%);
}
