@media (max-width: 1024px) {
  .hero__inner  { grid-template-columns: 1fr; }
  .hero__visual { display: none; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card--lead { grid-column: span 2; grid-row: auto; }
