(() => {
  'use strict';

  /* ── Cart state ──────────────────────────────────────────── */
  const cart = { items: [], get count() { return this.items.length; } };

  function updateCartBadge() {
    const badge = document.getElementById('cart-count');
    if (!badge) return;
    badge.textContent = cart.count;
    badge.hidden = cart.count === 0;
  }

  /* ── Toast notifications ─────────────────────────────────── */
  function showToast(icon, message) {
    const region = document.getElementById('toast-region');
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.setAttribute('role', 'status');
    toast.setAttribute('aria-live', 'polite');
    toast.innerHTML = `<span class="toast__icon" aria-hidden="true">${icon}</span><span>${message}</span>`;
    region.appendChild(toast);
    setTimeout(() => toast.remove(), 3100);
  }

  /* ── Add to cart ─────────────────────────────────────────── */
  function addToCart(name, btn) {
    cart.items.push(name);
    updateCartBadge();

    btn.setAttribute('aria-label', `${name} added to cart`);
    btn.textContent = '✓';
    btn.style.background = 'var(--green)';

    setTimeout(() => {
      btn.textContent = '+';
      btn.style.background = '';
      btn.setAttribute('aria-label', `Add ${name} to cart`);
    }, 1200);

    showToast('🛒', `<strong>${name}</strong> added to cart`);
  }

  /* ── Wishlist toggle ─────────────────────────────────────── */
  function toggleWishlist(btn, name) {
    const pressed = btn.getAttribute('aria-pressed') === 'true';
    btn.setAttribute('aria-pressed', String(!pressed));
    btn.textContent = !pressed ? '♥' : '♡';
    if (!pressed) {
      showToast('♥', `<strong>${name}</strong> saved to wishlist`);
    }
  }

  /* ── Category filter ─────────────────────────────────────── */
  function initCategoryFilter() {
    const pills = document.querySelectorAll('.cat-pill');
    pills.forEach(pill => {
      pill.addEventListener('click', () => {
        pills.forEach(p => { p.setAttribute('aria-pressed', 'false'); });
        pill.setAttribute('aria-pressed', 'true');
        const cat = pill.dataset.cat;
        const cards = document.querySelectorAll('.product-card[data-cat]');
        cards.forEach(card => {
          const matches = cat === 'all' || card.dataset.cat === cat;
          card.style.display = matches ? '' : 'none';
        });
      });
    });
  }

  /* ── Countdown timers ────────────────────────────────────── */
  function initTimers() {
    // Seed deal timers: 3 h 22 m from page load
    const endsAt = Date.now() + (3 * 3600 + 22 * 60) * 1000;
    document.querySelectorAll('.deal-card__timer').forEach(el => {
      el.setAttribute('data-ends', endsAt);
    });
    const timers = document.querySelectorAll('[data-ends]');
    function tick() {
      const now = Date.now();
      timers.forEach(el => {
        const diff = Math.max(0, Number(el.dataset.ends) - now);
        const h = Math.floor(diff / 3600000);
        const m = Math.floor((diff % 3600000) / 60000);
        const s = Math.floor((diff % 60000) / 1000);
        const pad = n => String(n).padStart(2, '0');
        const hEl = el.querySelector('.t-h');
        const mEl = el.querySelector('.t-m');
        const sEl = el.querySelector('.t-s');
        if (hEl) hEl.textContent = pad(h);
        if (mEl) mEl.textContent = pad(m);
        if (sEl) sEl.textContent = pad(s);
      });
    }
    tick();
    setInterval(tick, 1000);
  }

  /* ── Mobile nav toggle ───────────────────────────────────── */
  function initMobileNav() {
    const toggle = document.getElementById('menu-toggle');
    const nav    = document.getElementById('primary-nav');
    if (!toggle || !nav) return;

    toggle.addEventListener('click', () => {
      const expanded = toggle.getAttribute('aria-expanded') === 'true';
      toggle.setAttribute('aria-expanded', String(!expanded));
      nav.hidden = expanded;
      if (!expanded) {
        // animate in
        nav.style.maxHeight = nav.scrollHeight + 'px';
      } else {
        nav.style.maxHeight = '';
      }
    });
  }

  /* ── Newsletter form ─────────────────────────────────────── */
  function initNewsletter() {
    const form = document.getElementById('newsletter-form');
    if (!form) return;
    form.addEventListener('submit', e => {
      e.preventDefault();
      const input = form.querySelector('.newsletter__input');
      if (!input.value.trim()) return;
      showToast('🎉', 'You're subscribed! Check your inbox.');
      input.value = '';
    });
  }

  /* ── Hero product card click ─────────────────────────────── */
  function initHeroCards() {
    document.querySelectorAll('.hero__product-card').forEach(card => {
      card.addEventListener('click', () => {
        showToast('👀', 'Product detail page coming soon');
      });
      card.addEventListener('keydown', e => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); card.click(); }
      });
    });
  }

  /* ── Deal card CTA ───────────────────────────────────────── */
  function initDealCards() {
    document.querySelectorAll('.deal-cta').forEach(btn => {
      btn.addEventListener('click', () => {
        const name = btn.closest('.deal-card__content')?.querySelector('.deal-card__title')?.textContent;
        if (name) addToCart(name, btn);
      });
    });
  }

  /* ── Bind all add-to-cart buttons ────────────────────────── */
  function initAddToCart() {
    document.querySelectorAll('.add-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const card = btn.closest('.product-card');
        const name = card?.querySelector('.product-card__name')?.textContent ?? 'Item';
        addToCart(name.trim(), btn);
      });
    });
  }

  /* ── Smooth scroll for anchor links ─────────────────────── */
  function initSmoothScroll() {
    document.querySelectorAll('a[href^="#"]').forEach(a => {
      a.addEventListener('click', e => {
        const target = document.querySelector(a.getAttribute('href'));
        if (target) { e.preventDefault(); target.scrollIntoView({ behavior: 'smooth' }); }
      });
    });
  }

  /* ── Boot ────────────────────────────────────────────────── */
  document.addEventListener('DOMContentLoaded', () => {
    updateCartBadge();
    initCategoryFilter();
    initTimers();
    initMobileNav();
    initNewsletter();
    initHeroCards();
    initDealCards();
    initAddToCart();
    initSmoothScroll();
  });
})();
